package projector

import (
	_ "embed"
	"io/fs"
	"sort"
	"strings"
)

const (
	markdownMarker = "<!-- GENERATED by awf; remove this comment to take ownership -->"
	textMarker     = "# GENERATED by awf; remove this comment to take ownership"
)

//go:embed VERSION
var versionFile string

// Version is the release identity embedded in this binary.
var Version = strings.TrimSpace(versionFile)

// Output is one complete generated file.
type Output struct {
	Path  string
	Bytes []byte
	Mode  fs.FileMode
}

// Build returns the complete fixed output set for sources.
func Build(sources SourceTree) []Output {
	agents := markdownMarker + "\n" +
		"# Agent guide\n\n" +
		"This file is generated by AWF. Edit `.awf/project.md` and `.awf/topics/**/*.md`, then run this repository's documented render and check commands.\n\n" +
		"Use the repository's AWF command with `resolve` when repository context is needed: without paths for explicit global topics, or with paths for globals plus matching topics. Read the returned sources. Use the generated `awf-topics` and `awf-effort` skills for their respective workflows.\n\n" +
		"When installed, use `agentic-planning`, `agentic-implementing`, and `agentic-reviewing` for their general methods. Use `agentic-artifact-design` for substantial prose work and `agentic-code-design` for structural code judgment.\n" +
		string(sources.Project.Body)

	topicSkill := skillDocument("awf-topics", "Find and maintain path-routed current project guidance.",
		"# AWF topics\n\n"+
			"Topics are the only current-state knowledge layer. When repository context is needed, run the repository's documented AWF command with `resolve` for explicit global topics or `resolve <path>...` for globals plus topics matching any supplied path. Read every returned `.awf/topics/...md` source. Once the applicable current context is known, do not repeat the query before every edit.\n\n"+
			"Keep affected topics accurate with the implementation. Incorporate durable decisions and useful rationale into the applicable topics; future agents read topics rather than historical decision records to learn what currently applies.\n\n"+
			"A topic is ordinary Markdown with positive `paths` patterns in its frontmatter. The exact sole entry `paths: ['**']` declares an explicit global topic. AWF does not validate or otherwise interpret the body.\n")
	effortSkill := skillDocument("awf-effort", "Keep lightweight local continuity for an active effort.",
		"# AWF efforts\n\n"+
			"Use the repository's documented AWF command with `effort new <slug>`, `effort list`, `effort show <slug>`, and `effort finish <slug>`. Keep the outcome and success criteria, current state, next actions, artifact references, selected decision-relevant excerpts, and completion evidence in `.awf/efforts/<slug>/memory.md`. Attribute excerpts and distinguish quotations, summaries, agent proposals, and agreed decisions; do not reconstruct or retain complete sessions. Detailed criteria may live in an optional plan when memory points to it.\n\n"+
			"Plans and decision records are independent, optional aids: complexity can warrant a plan, a material choice can warrant a decision record, and an effort can need either, both, or neither. Use `plan new <effort-slug>` to create `.awf/efforts/<effort-slug>/plan.md` in an existing effort and `adr new <slug>` to create `docs/decisions/<slug>.md`. The commands are create-only conveniences; edit the files directly, and author either file without a scaffold when preferred. AWF treats their contents as opaque. When installed, use `agentic-planning`, `agentic-implementing`, and `agentic-reviewing` for general methods.\n\n"+
			"AWF does not manage Git or discover worktree topology. Without a worktree, the effort and implementation checkout coincide. With one, memory and plans remain in the primary checkout while the decision record and implementation belong to the implementation checkout. Record both locations in memory and handoffs. Run effort and plan commands from the primary checkout root; run ADR and implementation Git commands from the implementation checkout root. Run worktree creation, integration, removal, and branch cleanup from the primary checkout root. Read or edit known artifact paths directly; invoking a wrapper by absolute path does not change this working-directory rule.\n\n"+
			"When isolation helps, create a native worktree yourself from the primary checkout:\n\n"+
			"```sh\n"+
			"git worktree add -b awf/<slug> .awf/worktrees/<slug>\n"+
			"```\n\n"+
			"A decision record has one working copy in `docs/decisions`; memory references it. Commit the chosen decision and rationale during the effort. After verifying the implemented result and incorporating the durable decision and useful rationale into applicable topics, remove the record in a later implementation/topic-update commit. Preserve both commits through the repository's ordinary non-squash integration. Retrieve it later with:\n\n"+
			"```sh\n"+
			"git log --full-history -- docs/decisions/<slug>.md\n"+
			"git show <decision-commit>:docs/decisions/<slug>.md\n"+
			"```\n\n"+
			"Before closing an effort, compare the actual result with its success criteria, report unmet criteria and deviations, surface a changed goal rather than rewriting it as success, keep applicable topics accurate, and retire integrated decision records as above. `effort finish` enforces none of this meaning; it only moves the complete resident to `.awf/effort-archive/<slug>` without replacement.\n\n"+
			"After non-squash integration, clean up an isolated worktree explicitly, then finish the effort:\n\n"+
			"```sh\n"+
			"git worktree remove .awf/worktrees/<slug>\n"+
			"git branch -d awf/<slug>\n"+
			"```\n")

	bootstrap := strings.ReplaceAll(bootstrapScript, "@@VERSION@@", Version)
	outputs := []Output{
		{Path: "AGENTS.md", Bytes: []byte(agents), Mode: 0o644},
		{Path: "CLAUDE.md", Bytes: []byte(markdownMarker + "\n# Claude guidance\n\nFollow [`AGENTS.md`](AGENTS.md).\n"), Mode: 0o644},
		{Path: ".pi/skills/awf-topics/SKILL.md", Bytes: []byte(topicSkill), Mode: 0o644},
		{Path: ".claude/skills/awf-topics/SKILL.md", Bytes: []byte(topicSkill), Mode: 0o644},
		{Path: ".pi/skills/awf-effort/SKILL.md", Bytes: []byte(effortSkill), Mode: 0o644},
		{Path: ".claude/skills/awf-effort/SKILL.md", Bytes: []byte(effortSkill), Mode: 0o644},
		{Path: ".awf/.gitignore", Bytes: []byte(textMarker + "\n/efforts/\n/worktrees/\n/effort-archive/\n"), Mode: 0o644},
		{Path: "awf", Bytes: []byte(withScriptMarker(wrapperScript)), Mode: 0o755},
		{Path: ".awf/bootstrap.sh", Bytes: []byte(withScriptMarker(bootstrap)), Mode: 0o755},
	}
	sort.Slice(outputs, func(i, j int) bool { return outputs[i].Path < outputs[j].Path })
	return outputs
}

func skillDocument(name, description, body string) string {
	return "---\nname: " + name + "\ndescription: " + description + "\n---\n" + markdownMarker + "\n\n" + body
}

func withScriptMarker(script string) string {
	const shebang = "#!/usr/bin/env bash\n"
	return shebang + textMarker + "\n" + strings.TrimPrefix(script, shebang)
}

const wrapperScript = `#!/usr/bin/env bash
set -euo pipefail

binary="$(bash .awf/bootstrap.sh)"
exec "$binary" "$@"
`

const bootstrapScript = `#!/usr/bin/env bash
# Fetch a pinned AWF release, verify it, cache it, and print its binary path.
set -euo pipefail

AWF_VERSION="${AWF_VERSION:-@@VERSION@@}"
repo="hypnotox/agentic-workflows"
cache_dir="${XDG_CACHE_HOME:-$HOME/.cache}/awf/${AWF_VERSION}"
binary="${cache_dir}/awf"

if [ -x "$binary" ]; then
  printf '%s\n' "$binary"
  exit 0
fi

os="$(uname -s | tr '[:upper:]' '[:lower:]')"
arch="$(uname -m)"
case "$arch" in
  x86_64|amd64) arch="amd64" ;;
  arm64|aarch64) arch="arm64" ;;
  *) echo "awf bootstrap: unsupported architecture: $arch" >&2; exit 1 ;;
esac
case "$os" in
  linux|darwin) ;;
  *) echo "awf bootstrap: unsupported operating system: $os" >&2; exit 1 ;;
esac

asset="awf_${AWF_VERSION}_${os}_${arch}.tar.gz"
base="https://github.com/${repo}/releases/download/v${AWF_VERSION}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

curl -fsSL "${base}/${asset}" -o "${tmp}/${asset}"
curl -fsSL "${base}/checksums.txt" -o "${tmp}/checksums.txt"
if command -v sha256sum >/dev/null 2>&1; then
  (cd "$tmp" && grep " ${asset}$" checksums.txt | sha256sum -c - >&2)
else
  (cd "$tmp" && grep " ${asset}$" checksums.txt | shasum -a 256 -c - >&2)
fi

tar -xzf "${tmp}/${asset}" -C "$tmp"
mkdir -p "$cache_dir"
install -m 0755 "${tmp}/awf" "$binary"
printf '%s\n' "$binary"
`
